#!/bin/sh
set -eu

REPO="block/aittributor"
BINARY="aittributor"
INSTALL_DIR="${INSTALL_DIR:-/usr/local/bin}"

get_latest_version() {
    curl -fsSL "https://api.github.com/repos/${REPO}/releases/latest" | \
        grep '"tag_name":' | sed -E 's/.*"([^"]+)".*/\1/'
}

get_arch() {
    arch=$(uname -m)
    case "$arch" in
        x86_64|amd64) echo "x86_64" ;;
        aarch64|arm64) echo "aarch64" ;;
        *) echo "Unsupported architecture: $arch" >&2; exit 1 ;;
    esac
}

get_os() {
    os=$(uname -s)
    case "$os" in
        Darwin) echo "apple-darwin" ;;
        Linux) echo "unknown-linux-gnu" ;;
        *) echo "Unsupported OS: $os" >&2; exit 1 ;;
    esac
}

main() {
    version="${1:-$(get_latest_version)}"
    arch=$(get_arch)
    os=$(get_os)

    asset="${BINARY}-${arch}-${os}.bz2"
    url="https://github.com/${REPO}/releases/download/${version}/${asset}"

    echo "Downloading ${BINARY} ${version} for ${arch}-${os}..."

    tmpdir=$(mktemp -d)
    trap 'rm -rf "$tmpdir"' EXIT

    curl -fsSL "$url" | bunzip2 > "${tmpdir}/${BINARY}"
    chmod +x "${tmpdir}/${BINARY}"

    if [ -w "$INSTALL_DIR" ]; then
        mv "${tmpdir}/${BINARY}" "${INSTALL_DIR}/${BINARY}"
    else
        echo "Installing to ${INSTALL_DIR} (requires sudo)..."
        sudo mv "${tmpdir}/${BINARY}" "${INSTALL_DIR}/${BINARY}"
    fi

    echo "Installed ${BINARY} to ${INSTALL_DIR}/${BINARY}"
}

main "$@"

use std::ffi::{OsStr, OsString};
use std::path::Path;

pub struct Agent {
    pub process_names: &'static [&'static str],
    pub env_vars: &'static [(&'static str, &'static str)],
    pub email: &'static str,
    pub breadcrumb_dir: Option<&'static str>,
    pub breadcrumb_ext: Option<&'static str>,
    /// When true, process_names must match the basename exactly (not as a substring).
    /// Use for short names like "pi" that would otherwise false-positive on "pipefail" etc.
    pub exact_process_match: bool,
}

pub const KNOWN_AGENTS: &[Agent] = &[
    Agent {
        process_names: &["claude"],
        email: "Claude Code <noreply@anthropic.com>",
        breadcrumb_dir: Some(".claude/projects"),
        breadcrumb_ext: Some("jsonl"),
        ..Agent::default()
    },
    Agent {
        process_names: &["goose"],
        email: "Goose <opensource@block.xyz>",
        ..Agent::default()
    },
    Agent {
        process_names: &["cursor", "cursor-agent"],
        email: "Cursor <cursoragent@cursor.com>",
        ..Agent::default()
    },
    Agent {
        process_names: &["aider"],
        email: "Aider <noreply@aider.chat>",
        ..Agent::default()
    },
    Agent {
        process_names: &["windsurf"],
        email: "Windsurf <noreply@codeium.com>",
        ..Agent::default()
    },
    Agent {
        process_names: &["codex"],
        email: "Codex <noreply@openai.com>",
        breadcrumb_dir: Some(".codex/sessions"),
        breadcrumb_ext: Some("jsonl"),
        ..Agent::default()
    },
    Agent {
        process_names: &["copilot-agent"],
        email: "GitHub Copilot <noreply@github.com>",
        ..Agent::default()
    },
    // Copilot CLI is a separate terminal agent from the VS Code extension (copilot-agent above).
    // Must appear after copilot-agent since find_by_name uses contains() and "copilot" would
    // otherwise shadow the more specific "copilot-agent" match.
    Agent {
        process_names: &["copilot"],
        email: "Copilot <223556219+Copilot@users.noreply.github.com>",
        // Sessions stored as JSONL event logs in ~/.copilot/session-state/{session-id}/events.jsonl
        breadcrumb_dir: Some(".copilot/session-state"),
        breadcrumb_ext: Some("jsonl"),
        ..Agent::default()
    },
    Agent {
        process_names: &["amazon-q"],
        email: "Amazon Q Developer <noreply@amazon.com>",
        ..Agent::default()
    },
    Agent {
        process_names: &["amp"],
        email: "Amp <amp@ampcode.com>",
        ..Agent::default()
    },
    Agent {
        env_vars: &[("CLINE_ACTIVE", "true")],
        email: "Cline <noreply@cline.bot>",
        ..Agent::default()
    },
    Agent {
        process_names: &["gemini"],
        email: "Gemini CLI Agent <gemini-cli-agent@google.com>",
        ..Agent::default()
    },
    Agent {
        process_names: &["pi"],
        email: "Pi <noreply@pi.dev>",
        breadcrumb_dir: Some(".pi/agent/sessions"),
        breadcrumb_ext: Some("jsonl"),
        exact_process_match: true,
        ..Agent::default()
    },
    // TODO: OpenCode sessions are stored in SQLite (~/.local/share/opencode/opencode.db),
    // not flat files. Breadcrumb scanning would require a new SQLite-based strategy.
    Agent {
        process_names: &["opencode"],
        email: "opencode <noreply@opencode.ai>",
        ..Agent::default()
    },
];

impl Agent {
    const fn default() -> Self {
        Agent {
            process_names: &[],
            env_vars: &[],
            email: "",
            breadcrumb_dir: None,
            breadcrumb_ext: None,
            exact_process_match: false,
        }
    }

    /// Extract the bare email address from a "Name <addr>" string.
    /// e.g. "Claude Code <noreply@anthropic.com>" → "noreply@anthropic.com"
    pub fn extract_email_addr(email: &str) -> &str {
        email
            .split('<')
            .nth(1)
            .and_then(|s| s.split('>').next())
            .unwrap_or(email)
    }

    pub fn find_by_name(name: &str) -> Option<&'static Agent> {
        let path = Path::new(name);
        let basename = path.file_name().and_then(|n| n.to_str()).unwrap_or(name);
        let basename_lower = basename.to_lowercase();

        KNOWN_AGENTS.iter().find(|agent| {
            !agent.process_names.is_empty()
                && agent.process_names.iter().any(|&pn| {
                    if agent.exact_process_match {
                        basename_lower == pn
                    } else {
                        basename_lower.contains(pn)
                    }
                })
        })
    }

    pub fn find_by_env() -> Option<&'static Agent> {
        KNOWN_AGENTS.iter().find(|agent| {
            !agent.env_vars.is_empty()
                && agent
                    .env_vars
                    .iter()
                    .all(|(key, value)| std::env::var(key).ok().as_deref() == Some(*value))
        })
    }

    pub fn find_for_process(process: &sysinfo::Process) -> Option<&'static Agent> {
        Self::find_for_command(process.name(), process.cmd())
    }

    fn find_for_command(name: &OsStr, command: &[OsString]) -> Option<&'static Agent> {
        let name = name.to_string_lossy();
        if let Some(agent) = Self::find_by_name(&name) {
            return Some(agent);
        }

        // Check basename(argv[0])
        if let Some(arg0) = command.first() {
            let arg0_str = arg0.to_string_lossy();
            if let Some(agent) = Self::find_by_name(&arg0_str) {
                return Some(agent);
            }

            // Login shells prefix argv[0] with '-'; shell -c arguments contain code.
            let executable = Path::new(arg0)
                .file_name()
                .and_then(OsStr::to_str)
                .map(|name| name.strip_prefix('-').unwrap_or(name));
            if matches!(
                executable,
                Some("sh" | "bash" | "dash" | "ash" | "zsh" | "ksh" | "fish" | "csh" | "tcsh")
            ) && command
                .iter()
                .skip(1)
                .map(|arg| arg.to_string_lossy())
                .take_while(|arg| arg.starts_with('-') && arg != "--")
                .any(|arg| {
                    arg == "--command"
                        || arg
                            .strip_prefix('-')
                            .is_some_and(|flags| !flags.starts_with('-') && flags.contains('c'))
                })
            {
                return None;
            }
        }

        // Check first basename(argv[1:]) that doesn't start with '-'
        if let Some(arg) = command.iter().skip(1).find(|arg| {
            let arg_str = arg.to_string_lossy();
            !arg_str.starts_with('-')
        }) {
            let arg_str = arg.to_string_lossy();
            if let Some(agent) = Self::find_by_name(&arg_str) {
                return Some(agent);
            }
        }

        None
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Read;
    use std::process::{Command, Stdio};
    use sysinfo::{ProcessRefreshKind, RefreshKind, System, UpdateKind};

    #[test]
    fn shell_command_text_does_not_identify_an_agent() {
        for (shell, flag) in [("sh", "-c"), ("bash", "-c"), ("bash", "-lc")] {
            let mut child = Command::new(shell)
                .args([
                    flag,
                    "printf ready; read -r ignored # git commit -m 'chore: deploy goose-example'",
                ])
                .stdin(Stdio::piped())
                .stdout(Stdio::piped())
                .spawn()
                .unwrap();
            // Wait until the shell has started and is blocked on stdin.
            child.stdout.as_mut().unwrap().read_exact(&mut [0; 5]).unwrap();
            let system = System::new_with_specifics(
                RefreshKind::nothing().with_processes(ProcessRefreshKind::nothing().with_cmd(UpdateKind::Always)),
            );
            let process = system.process(sysinfo::Pid::from_u32(child.id())).unwrap();
            let detected = Agent::find_for_process(process).map(|agent| agent.email);
            child.kill().unwrap();
            child.wait().unwrap();

            assert_eq!(detected, None, "{shell} {flag} was mistaken for an agent");
        }
    }

    #[test]
    fn interpreter_scripts_still_identify_agents() {
        for (name, args, email) in [
            (
                "node",
                vec!["/usr/bin/node", "/opt/codex-acp.js"],
                "Codex <noreply@openai.com>",
            ),
            (
                "python3",
                vec!["python3", "-u", "/opt/goose.py"],
                "Goose <opensource@block.xyz>",
            ),
            ("bash", vec!["bash", "/opt/codex.sh"], "Codex <noreply@openai.com>"),
            (
                "codex",
                vec!["codex", "exec", "goose-example"],
                "Codex <noreply@openai.com>",
            ),
        ] {
            let command: Vec<OsString> = args.into_iter().map(OsString::from).collect();
            assert_eq!(
                Agent::find_for_command(OsStr::new(name), &command).map(|agent| agent.email),
                Some(email),
                "failed to identify {command:?}",
            );
        }
    }

    #[test]
    fn shell_inline_command_flags_do_not_identify_agents() {
        for (name, executable, flag) in [
            ("bash", "bash", "-lc"),
            ("zsh", "zsh", "-ic"),
            ("fish", "fish", "--command"),
            ("bash", "-bash", "-c"),
            ("zsh", "-zsh", "-ic"),
        ] {
            let command = [executable, flag, "git commit -m 'deploy goose-example'"].map(OsString::from);
            assert!(Agent::find_for_command(OsStr::new(name), &command).is_none());
        }
    }
}

use std::fs;
use std::path::{Path, PathBuf};

use crate::agent::Agent;

/// Returns the current branch name for the repo, or `None` when it can't be
/// determined (e.g. detached HEAD, or `git` isn't available).
///
/// Uses `git symbolic-ref --short -q HEAD`, which prints the branch and exits
/// zero on a normal checkout, and prints nothing / exits non-zero on a detached
/// HEAD. We treat both failure and empty output as "unknown".
pub fn current_branch(repo_path: &Path) -> Option<String> {
    let output = std::process::Command::new("git")
        .arg("-C")
        .arg(repo_path)
        .args(["symbolic-ref", "--short", "-q", "HEAD"])
        .output()
        .ok()?;

    if !output.status.success() {
        return None;
    }

    let branch = String::from_utf8_lossy(&output.stdout).trim().to_string();
    if branch.is_empty() { None } else { Some(branch) }
}

pub fn find_git_root(start_path: &Path) -> Option<PathBuf> {
    let mut current = start_path.to_path_buf();

    loop {
        let git_dir = current.join(".git");
        if git_dir.exists() {
            return Some(current);
        }

        current = current.parent()?.to_path_buf();
    }
}

pub fn append_trailers(commit_msg_file: &PathBuf, agent: &Agent, debug: bool) -> std::io::Result<()> {
    let content = fs::read_to_string(commit_msg_file)?;

    let addr = Agent::extract_email_addr(agent.email);
    let content_lower = content.to_lowercase();
    let has_co_author = content_lower.contains("co-authored-by:") && content_lower.contains(&addr.to_lowercase());

    if has_co_author {
        if debug {
            eprintln!("\n=== Git Command ===");
            eprintln!("Co-authored-by trailer already present, skipping git interpret-trailers");
        }
        return Ok(());
    }

    let co_authored = format!("Co-authored-by: {}", agent.email);

    if debug {
        eprintln!("\n=== Git Command ===");
        eprintln!(
            "git interpret-trailers --in-place --trailer \"{}\" --if-exists addIfDifferent \"{}\"",
            co_authored,
            commit_msg_file.display()
        );
    }

    let mut cmd = std::process::Command::new("git");
    cmd.arg("interpret-trailers")
        .arg("--in-place")
        .arg("--trailer")
        .arg(&co_authored)
        .arg("--if-exists")
        .arg("addIfDifferent")
        .arg(commit_msg_file);

    let output = cmd.output()?;

    if !output.status.success() {
        return Err(std::io::Error::other(format!(
            "git interpret-trailers failed: {}",
            String::from_utf8_lossy(&output.stderr)
        )));
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::process::Command;
    use tempfile::TempDir;

    #[test]
    fn test_current_branch_reads_checked_out_branch() {
        let dir = TempDir::new().unwrap();
        let path = dir.path();

        // `git init` followed by pointing HEAD at a branch gives a deterministic
        // branch name without needing any commits or user git config.
        assert!(
            Command::new("git")
                .arg("-C")
                .arg(path)
                .arg("init")
                .arg("-q")
                .status()
                .unwrap()
                .success()
        );
        assert!(
            Command::new("git")
                .arg("-C")
                .arg(path)
                .args(["symbolic-ref", "HEAD", "refs/heads/feature-x"])
                .status()
                .unwrap()
                .success()
        );

        assert_eq!(current_branch(path).as_deref(), Some("feature-x"));
    }

    #[test]
    fn test_current_branch_none_outside_repo() {
        let dir = TempDir::new().unwrap();
        assert_eq!(current_branch(dir.path()), None);
    }
}

mod agent;
mod breadcrumbs;
mod git;

use clap::Parser;
use std::collections::{HashSet, VecDeque};
use std::path::PathBuf;
use std::sync::mpsc;
use std::time::Duration;
use sysinfo::{Pid, ProcessRefreshKind, RefreshKind, System, UpdateKind};

use agent::Agent;
use git::{append_trailers, find_git_root};

#[derive(Parser)]
#[command(name = "aittributor", version)]
#[command(about = "Git prepare-commit-msg hook that adds AI agent attribution")]
struct Cli {
    /// Path to the commit message file
    commit_msg_file: Option<PathBuf>,

    /// Commit message source (message, template, merge, squash, or commit)
    #[arg(default_value = "")]
    commit_source: String,

    /// Commit SHA (when amending)
    #[arg(default_value = "")]
    commit_sha: String,

    /// Enable debug output
    #[arg(long)]
    debug: bool,
}

/// Accumulates debug information while scanning a process tree.
///
/// All tracking is skipped unless `debug` is set, so the normal
/// (non-debug) code path stays allocation-free.
struct ScanReport {
    debug: bool,
    scanned: HashSet<Pid>,
    findings: Vec<String>,
    /// Emails already reported, to avoid duplicate "found" lines when the
    /// same agent shows up under multiple siblings.
    logged: HashSet<&'static str>,
}

impl ScanReport {
    fn new(debug: bool) -> Self {
        Self {
            debug,
            scanned: HashSet::new(),
            findings: Vec::new(),
            logged: HashSet::new(),
        }
    }

    fn mark_scanned(&mut self, pid: Pid) {
        if self.debug {
            self.scanned.insert(pid);
        }
    }

    fn record_match(&mut self, agent: &'static Agent, pid: Pid, name: &str) {
        // `insert` returns false if the email was already recorded.
        if self.debug && self.logged.insert(agent.email) {
            self.findings.push(format!(
                "  found {} (pid {}, process \"{}\", cwd matches repo)",
                agent.email, pid, name
            ));
        }
    }

    fn flush_into(self, log: &mut Vec<String>) {
        if !self.debug {
            return;
        }
        log.push(format!("  scanned {} processes", self.scanned.len()));
        if self.findings.is_empty() {
            log.push("  no match".to_string());
        } else {
            log.extend(self.findings);
        }
    }
}

fn walk_ancestry(system: &System, log: &mut Vec<String>, debug: bool) -> Vec<&'static Agent> {
    let mut current_pid = Pid::from_u32(std::process::id());
    let mut agents = Vec::new();
    let mut walked = 0usize;
    let mut findings = Vec::new();

    while let Some(process) = system.process(current_pid) {
        walked += 1;
        if let Some(agent) = Agent::find_for_process(process) {
            if debug {
                findings.push(format!(
                    "  found {} (pid {}, process \"{}\")",
                    agent.email,
                    current_pid,
                    process.name().to_string_lossy()
                ));
            }
            agents.push(agent);
        }

        match process.parent() {
            Some(parent_pid) if parent_pid != current_pid => {
                current_pid = parent_pid;
            }
            _ => break,
        }
    }

    if debug {
        log.push(format!("  walked {} processes", walked));
        if findings.is_empty() {
            log.push("  no match".to_string());
        } else {
            log.extend(findings);
        }
    }

    agents
}

fn check_process_tree(
    system: &System,
    root_pid: Pid,
    repo_path: &PathBuf,
    report: &mut ScanReport,
) -> Vec<&'static Agent> {
    let mut queue = VecDeque::new();
    let mut visited = HashSet::new();
    let mut agents = Vec::new();

    queue.push_back(root_pid);

    while let Some(pid) = queue.pop_front() {
        if !visited.insert(pid) {
            continue;
        }

        let process = match system.process(pid) {
            Some(p) => p,
            None => continue,
        };

        report.mark_scanned(pid);

        if let Some(agent) = Agent::find_for_process(process)
            && let Some(cwd) = process.cwd()
            && cwd.starts_with(repo_path)
        {
            report.record_match(agent, pid, &process.name().to_string_lossy());
            agents.push(agent);
        }

        for child in system.processes().values() {
            if child.parent() == Some(pid) {
                queue.push_back(child.pid());
            }
        }
    }

    agents
}

fn walk_ancestry_and_descendants(
    system: &System,
    repo_path: &PathBuf,
    log: &mut Vec<String>,
    debug: bool,
) -> Vec<&'static Agent> {
    let mut current_pid = Pid::from_u32(std::process::id());
    let mut checked_ancestors = HashSet::new();
    let mut agents = Vec::new();
    let mut report = ScanReport::new(debug);

    while let Some(process) = system.process(current_pid) {
        if !checked_ancestors.insert(current_pid) {
            break;
        }

        let parent_pid = match process.parent() {
            Some(pid) if pid != current_pid => pid,
            _ => break,
        };

        for sibling in system.processes().values() {
            if sibling.parent() != Some(parent_pid) {
                continue;
            }

            agents.extend(check_process_tree(system, sibling.pid(), repo_path, &mut report));
        }

        current_pid = parent_pid;
    }

    report.flush_into(log);

    agents
}

fn detect_agents(log: &mut Vec<String>, debug: bool) -> Vec<&'static Agent> {
    let mut agents = Vec::new();

    if debug {
        log.push("strategy: environment variables".to_string());
    }
    match Agent::find_by_env() {
        Some(agent) => {
            if debug {
                let vars = agent
                    .env_vars
                    .iter()
                    .map(|(key, _)| *key)
                    .collect::<Vec<_>>()
                    .join(", ");
                log.push(format!("  found {} (env: {})", agent.email, vars));
            }
            agents.push(agent);
        }
        None => {
            if debug {
                log.push("  no match".to_string());
            }
        }
    }

    let current_dir = match std::env::current_dir() {
        Ok(d) => d,
        Err(_) => return agents,
    };
    let repo_path = find_git_root(&current_dir).unwrap_or(current_dir);
    if debug {
        log.push(format!("repository: {}", repo_path.display()));
        log.push("strategy: process ancestry".to_string());
    }

    let system = System::new_with_specifics(
        RefreshKind::nothing().with_processes(
            ProcessRefreshKind::nothing()
                .with_cmd(UpdateKind::Always)
                .with_cwd(UpdateKind::Always),
        ),
    );

    agents.extend(walk_ancestry(&system, log, debug));

    if debug {
        log.push("strategy: process tree (siblings and descendants)".to_string());
    }
    agents.extend(walk_ancestry_and_descendants(&system, &repo_path, log, debug));

    agents
}

fn breadcrumb_fallback(log: &mut Vec<String>, debug: bool) -> Vec<&'static Agent> {
    let current_dir = std::env::current_dir().unwrap_or_default();
    let repo_path = find_git_root(&current_dir).unwrap_or(current_dir);
    breadcrumbs::detect_agents_from_breadcrumbs(&repo_path, log, debug)
}

fn first_detected_agent(debug: bool) -> Option<&'static Agent> {
    // The breadcrumb scan runs on a separate thread, so each strategy buffers
    // its debug output into a `Vec<String>` instead of printing directly. We
    // print everything in a fixed order afterwards to keep the report readable.
    let (bc_tx, bc_rx) = mpsc::channel();
    std::thread::spawn(move || {
        let mut bc_log = Vec::new();
        let bc_agents = breadcrumb_fallback(&mut bc_log, debug);
        let _ = bc_tx.send((bc_agents, bc_log));
    });

    let mut log = Vec::new();
    let mut agents = detect_agents(&mut log, debug);

    if let Ok((bc_agents, bc_log)) = bc_rx.recv() {
        log.extend(bc_log);
        agents.extend(bc_agents);
    }

    let chosen = agents.into_iter().next();

    if debug {
        eprintln!("=== aittributor detection ===");
        for line in &log {
            eprintln!("{}", line);
        }
        match chosen {
            Some(agent) => eprintln!("\noutcome: attributing to {}", agent.email),
            None => eprintln!("\noutcome: no agent detected"),
        }
    }

    chosen
}

fn run(cli: Cli) {
    let agent = first_detected_agent(cli.debug);

    let Some(commit_msg_file) = cli.commit_msg_file else {
        match agent {
            Some(a) => println!("{}", a.email),
            None => {
                eprintln!("No agent found");
                std::process::exit(1);
            }
        }
        return;
    };

    if let Some(agent) = agent
        && let Err(e) = append_trailers(&commit_msg_file, agent, cli.debug)
    {
        eprintln!("aittributor: failed to append trailers: {}", e);
    }
}

fn main() {
    let cli = Cli::parse();

    let (tx, rx) = mpsc::channel();
    std::thread::spawn(move || {
        run(cli);
        let _ = tx.send(());
    });

    if rx.recv_timeout(Duration::from_secs(1)).is_err() {
        eprintln!("aittributor: timed out, skipping attribution. Check https://github.com/block/aittributor/issues");
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
