            "/Users/foo/monorepo/apps/service-a",
            Path::new("/Users/foo/monorepo")
        ));
        assert!(!cwd_matches_repo(
            "/Users/foo/aittributor2",
            Path::new("/Users/foo/aittributor")
        ));
    }

